  "wt9bn": "\"Membangun jembatan\" – memakai benteng untuk melindungi raja dari skak",
  "1xfmuyn": "Tukar benteng",
  "de2frr": "Posisi Lucena: raja putih di d8 di depan pion. Bawa benteng ke baris ke-4 untuk \"membangun jembatan\", lalu promosikan! Komputer bermain sebagai Hitam.",
  "ok3r28": "Memotong raja",
  "60x3bw": "Mengapa memakai benteng untuk \"memotong\" raja lawan di sepanjang lajur atau baris?",
  "1ui0cjd": "Raja lawan tidak sempat kembali untuk menghentikan pion",
  "ww32hs": "Untuk menukar benteng",
  "x3268c": "Untuk menjaga raja Anda tetap aman",
  "19y4dfu": "Gajah berwarna salah",
  "1lyiebm": "Raja, gajah, dan pion h, tetapi gajah tidak mengendalikan petak promosi h8 dan raja hitam ada di sudut. Apa hasilnya?",
  "1y0ib49": "Ulasan akhir permainan benteng",
  "17c069s": "Perhitungan & kelulusan",
  "1oaiv9p": "Langkah memaksa, pemeriksaan blunder, dan ujian akhir",
  "v4phrp": "Langkah memaksa",
  "1d38kk9": "Saat menghitung, dalam urutan apa Anda melihat langkah terlebih dahulu?",
  "28ctmc": "Skak – makan – ancaman",
  "jao6z3": "Langkah pion – pengembangan – rokade",
  "xib0or": "Langkah raja – ratu – benteng",
  "16r9n51": "Sebelum menyentuh bidak, apa pemeriksaan terakhirnya?",
  "1fue8p6": "Setelah langkah ini, bisakah lawan saya menskak, memakan, atau mengancam sesuatu?",
  "1i9uwoc": "Bergerak cepat",
  "1q4l3xi": "Hanya melihat bidak sendiri",
  "3vfpc2": "Mulailah dengan langkah memaksa! Mat dalam 2.",
  "ai8bft": "Berkorban untuk menang",
  "1c4vdgv": "Satu pelindung punya dua tugas. Mat dalam 2!",
  "1ovpig9": "Menuntaskan permainan",
  "1s3t19v": "Unggul jauh tidak berarti apa-apa jika tidak dituntaskan: skakmat raja hitam dalam paling banyak 15 langkah!",
